function tariffHead(){return '<div class="document-head"><h2>ТАРИФЫ</h2><p>на услуги Инвестиционного посредника и Инвестиционного консультанта<br>ООО «FULL STOCK GROUP»</p><p class="effective">* действуют с 01.08.2016г.</p></div>'}
function tariffNotes(){return '<div class="footnotes"><p>1. Информация по запросам уполномоченного государственного органа (ЦКРРЦБ), Центрального депозитария, судебных и иных органов в соответствии с законодательством Республики Узбекистан предоставляется на безвозмездной основе.</p><p>2. Инвестиционный посредник, в случае изменения настоящих тарифов, уведомляет Клиентов, не менее чем за 30 (тридцать) календарных дней до вступления в силу таких изменений, путем опубликования новых тарифов на официальном веб-сайте Инвестиционного посредника (www.fsg.uz).</p></div>'}
function pairRows(a,b){return `<tr><th colspan="3" class="plan-head" scope="colgroup">Тарифный план «${a.name}»</th><th colspan="3" class="plan-head" scope="colgroup">Тарифный план «${b.name}»</th></tr><tr>${[a,b].map(()=>'<th scope="col">Сумма сделки *</th><th scope="col">Тариф<br>в % от<br>суммы сделки</th><th scope="col">Примечание</th>').join('')}</tr>${a.rows.map((row,i)=>`<tr><td>${row[0]}</td><td class="rate">${row[1]}</td>${i===0?`<td rowspan="3" class="plan-note">${a.note}<br>${tariffAgreement}</td>`:''}<td>${b.rows[i][0]}</td><td class="rate">${b.rows[i][1]}</td>${i===0?`<td rowspan="3" class="plan-note">${b.note}<br>${tariffAgreement}</td>`:''}</tr>`).join('')}`}
function renderTariffs(){return `<section class="tariff-main container"><div class="tariff-intro"><h1>Тарифы ООО «FULL STOCK GROUP»</h1><p>на услуги Инвестиционного посредника и Инвестиционного консультанта</p></div><article class="tariff-document" aria-label="Тарифы на услуги FULL STOCK GROUP">${tariffHead()}<h3>БРОКЕРСКИЕ УСЛУГИ:</h3><p class="table-caption">Комиссионное вознаграждение по сделкам за Национальную валюту (СУМ) и СКВ (USD, EURO, RUB и др.)</p><div class="table-scroll broker-desktop" role="region" aria-label="Брокерские тарифы"><table class="tariff-table broker-table"><caption class="sr-only">Тарифные планы START, VIP, FINANCE и IPO/PO</caption><colgroup><col class="amount"><col class="rate-col"><col class="note-col"></colgroup><colgroup><col class="amount"><col class="rate-col"><col class="note-col"></colgroup><tbody>${pairRows(tariffPlans[0],tariffPlans[1])}${pairRows(tariffPlans[2],tariffPlans[3])}</tbody></table></div>${responsiveBrokerPlans()}<div class="footnotes"><p>* в случае расчетов суммы сделки в СКВ, сумма сделки определяется путем произведения в национальной валюте по соответствующему курсу ЦБ РУз на дату заключения Поручения на покупку или продажу ценных бумаг</p></div>${tariffNotes()}<section class="doc-section">${tariffHead()}<h3>ДЕПОЗИТАРНЫЕ УСЛУГИ:</h3><div class="table-scroll" role="region" aria-label="Бесплатные депозитарные услуги"><table class="tariff-table depo-free"><thead><tr><th colspan="2" scope="colgroup">Бесплатные услуги</th></tr></thead><tbody>${freeServices.map(row=>`<tr><td>${row[0]}</td><td>${row[1]}</td></tr>`).join('')}</tbody></table></div><p class="footnotes">* Оплачиваются только услуги Центрального депозитария</p><div class="table-scroll" role="region" aria-label="Платные депозитарные услуги"><table class="tariff-table paid-table"><thead><tr><th colspan="2" scope="colgroup">Платные услуги</th></tr><tr><th scope="col">Наименование услуги</th><th scope="col">Тариф в % от суммы сделки</th></tr></thead><tbody>${paidServices.map(row=>row[1]===null?`<tr><td colspan="2" class="group-cell">${row[0]}</td></tr>`:`<tr><td>${row[0]}</td><td class="rate">${row[1]}</td></tr>`).join('')}</tbody></table></div><p class="footnotes">В случае сделок и операций свыше 1 млрд.сум и/или количества сделок и операций свыше 500, окончательная ставка устанавливается индивидуально, но при достижении добровольного согласия Клиента</p>${tariffNotes()}</section><section class="doc-section">${tariffHead()}<h3>КОНСУЛЬТАЦИОННЫЕ УСЛУГИ:</h3><ul class="consult-list">${consultingServices.map(t=>`<li>${t}</li>`).join('')}</ul>${tariffNotes()}</section></article></section>`}

function responsiveBrokerPlans(){return `<div class="broker-responsive">${tariffPlans.map(plan=>`<section class="broker-plan"><h4>Тарифный план «${plan.name}»</h4><table class="tariff-table broker-plan-table"><caption class="sr-only">Ставки тарифного плана ${plan.name}</caption><thead><tr><th scope="col">Сумма сделки *</th><th scope="col">Тариф, % от суммы сделки</th></tr></thead><tbody>${plan.rows.map(row=>`<tr><td>${row[0]}</td><td class="rate">${row[1]}</td></tr>`).join('')}</tbody></table><div class="broker-plan-notes"><h5>Примечание</h5><p>${plan.note}</p><p>${tariffAgreement}</p></div></section>`).join('')}</div>`}
